import React, { useEffect, useState } from 'react';

function FusionDashboard() {
  const [fusionData, setFusionData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);

  // جلب البيانات الحالية
  const fetchData = () => {
    setLoading(true);
    fetch('/api/v1/fusion/latest')
      .then(res => res.json())
      .then(data => {
        setFusionData(data.report || []);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData();
  }, []);

  // تشغيل دورة Fusion جديدة
  const runFusion = () => {
    setRunning(true);
    fetch('/api/v1/fusion/run', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ description: 'New cycle' })
    })
      .then(res => res.json())
      .then(data => {
        setFusionData(prev => [...prev, data.cycle]);
        setRunning(false);
      })
      .catch(err => {
        console.error(err);
        setRunning(false);
      });
  };

  if (loading) return <div>Loading Fusion Dashboard...</div>;

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1>Fusion Dashboard</h1>
      <button onClick={runFusion} disabled={running} style={{ marginBottom: '10px' }}>
        {running ? 'Running...' : 'Run Fusion'}
      </button>
      <p>Total cycles: {fusionData.length}</p>
      <table border="1" cellPadding="5" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr>
            {fusionData[0] && Object.keys(fusionData[0]).map(key => <th key={key}>{key}</th>)}
          </tr>
        </thead>
        <tbody>
          {fusionData.map((item, idx) => (
            <tr key={idx}>
              {Object.values(item).map((val, i) => <td key={i}>{JSON.stringify(val)}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default FusionDashboard;
