import { useEffect, useState } from "react";
import { loadFull } from "tsparticles";
import Particles from "react-tsparticles";
import "./Landing.css";

export default function Landing() {
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setTimeout(() => setLoaded(true), 100);
  }, []);

  const particlesInit = async (main) => {
    await loadFull(main);
  };

  const particlesOptions = {
    background: { color: { value: "#0a0a0a" } },
    fpsLimit: 60,
    interactivity: {
      events: { onHover: { enable: true, mode: "repulse" } },
      modes: { repulse: { distance: 120, duration: 0.5 } }
    },
    particles: {
      color: { value: ["#ffd700", "#ffec99", "#ffc107"] },
      links: { enable: true, color: "#ffd700", distance: 160, opacity: 0.2, width: 1 },
      collisions: { enable: false },
      move: { enable: true, speed: 1, direction: "none", random: true, straight: false, outModes: "bounce" },
      number: { value: 80, density: { enable: true, area: 900 } },
      opacity: { value: { min: 0.3, max: 0.8 }, anim: { enable: true, speed: 0.5, opacity_min: 0.3, sync: false } },
      shape: { type: "circle" },
      size: { value: { min: 1, max: 5 } }
    },
    detectRetina: true
  };

  return (
    <div className="landing">
      <Particles id="tsparticles" init={particlesInit} options={particlesOptions} />
      <div className={`landing-overlay ${loaded ? "fade-in" : ""}`}>
        <header className="landing-header">
          <h1>SIRAJ</h1>
          <p>Artificial Intelligence Core Platform</p>
        </header>
        <div className="landing-cta">
          <a href="/fusion" className="btn-gold">Enter Platform</a>
        </div>
        <footer className="landing-footer">
          <p>© 2026 SIRAJ. All rights reserved.</p>
        </footer>
      </div>
    </div>
  );
}
